 */
function quotaGateContextOf(actualParams, params, ticketKey, customParams, expectedBranch) {
    return {
        ticketKey: ticketKey,
        customParams: customParams,
        metadata: actualParams.metadata || null,
        expectedBranch: expectedBranch,
        branchName: null,
