// ctx (standalone recovery) get a minimal derived one.
function quotaContextOf(ctx, ticketKey, customParams) {
    if (ctx) return ctx;
    return {
        ticketKey: ticketKey,
        customParams: customParams,
        metadata: null,
        expectedBranch: null,
        branchName: null,
