    }
}

function executePartialPushPlan(cliTool, config, ticketKey, plan, currentBranch) {
    if (!plan) {
        return;
    }
    if (plan.needsCheckout) {
        console.log('Switching partial work from ' + (currentBranch || '(unknown)') +
