+var GH1121_OUTAGE_LOG = [
+    'zai/glm-5.3-flash returned 500 {"code":"1234","message":"Internal network failure"} (attempt 1/6)',
+    'zai/glm-5.3-flash returned 500 {"code":"1234","message":"Internal network failure"} (attempt 2/6)',
