+        assert.deepEqual(quotaBreaker.extractOutageCodes(GH1121_OUTAGE_LOG), ['500', '429']);
+        assert.deepEqual(quotaBreaker.extractOutageModels('Provider chain exhausted: 2 of 2'), [],
